170	     * the first '-' of {@code '<REGION>-<HASH8>'}). When no customerCode has been assigned this
171	     * falls back to the canonical region derived from the owner via {@link CityRegionResolver},
172	     * preferring the postcode over the city, or 'UNKNOWN' when neither yields a known region.
173	     */
174	    String locality(Owner owner) {
175	        String customerCode = owner.getCustomerCode();
176	        if (customerCode != null) {
177	            int dash = customerCode.indexOf('-');
178	            if (dash >= 0) {
179	                return customerCode.substring(0, dash);
180	            }
181	        }
182	        return cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
183	    }
