231	     * points, level 2 for 2-3 points, level 3 for 4-5 points and level 4 for 6 or more points.
232	     */
233	    int levelForPoints(int points) {
234	        if (points >= 6) {
235	            return 4;
236	        }
237	        if (points >= 4) {
238	            return 3;
239	        }
240	        if (points >= 2) {
241	            return 2;
242	        }
243	        return 1;
244	    }
