284	     * trailing dot, e.g. 'J.S.'.
285	     */
286	    String initials(Owner owner) {
287	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
288	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
289	    }
290	
291	    public abstract Owner toOwner(OwnerDto ownerDto);
292	
293	    @Mapping(target = "id", ignore = true)
294	    @Mapping(target = "pets", ignore = true)
295	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
296	
