302	        OwnerPageDto ownerPageDto = new OwnerPageDto();
303	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
304	        ownerPageDto.setPage(ownerPage.getNumber());
305	        ownerPageDto.setSize(ownerPage.getSize());
306	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
307	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
308	        return ownerPageDto;
309	    }
